"""Exact 2-Selmer groups of congruent number curves C_d : y^2 = x(x - d)(x + d).

Written independently of scratch/rs-pole.  Kummer map P -> (x, x - d) in (Q*/Q*^2)^2,
with the usual replacement when a coordinate vanishes:
  (d,0) -> (d, 2),  (-d,0) -> (-d, -2d),  (0,0) -> (-1, -d).
Local images:
  * odd p | d : span of the three 2-torsion images (dimension 2 = dim E(Q_p)/2E(Q_p));
  * odd p not dividing d : unramified classes (automatic for candidates supported on {-1,2,p|d});
  * real place : d > 0 gives span{(-,-)}, d < 0 gives span{(-,+)} (dimension 1);
  * p = 2 : generated by Kummer images of explicit rational points of C_{d0}(Q_2), where d0 is a
    small representative of the class of d in Q_2*/Q_2*^2; sampling stops once dimension 3
    (= dim E(Q_2)/2E(Q_2)) is reached, so the computed image is exact.
Selmer group = candidates in <-1, 2, primes of d>^2 whose localizations lie in all local images.
Linear algebra over F_2 with Python integers as bit vectors.
"""
import random
from fractions import Fraction as Fr
from functools import lru_cache


def vp(n, p):
    n = abs(n)
    k = 0
    while n % p == 0:
        n //= p
        k += 1
    return k


def leg(a, p):
    """Legendre symbol bit: 0 if a is a nonzero square mod odd p, 1 if not."""
    a %= p
    assert a != 0
    return 0 if pow(a, (p - 1) // 2, p) == 1 else 1


def cls2(r):
    """Class of nonzero rational r in Q_2*/Q_2*^2 as 3 bits (v mod 2, eps, omega)."""
    r = Fr(r)
    num, den = r.numerator, r.denominator
    v = vp(num, 2) - vp(den, 2)
    u = (num // 2 ** vp(num, 2)) * (den // 2 ** vp(den, 2))  # same class as num/den unit
    u %= 8
    eps = ((u - 1) // 2) % 2
    om = ((u * u - 1) // 8) % 2
    return (v % 2) | (eps << 1) | (om << 2)


def is_sq_Q2(r):
    r = Fr(r)
    return r != 0 and cls2(r) == 0


def kummer(x, d):
    """Kummer image (first, second) of an affine point with abscissa x on C_d, as rationals."""
    x = Fr(x)
    if x == 0:
        return (Fr(-1), Fr(-d))
    if x == d:
        return (Fr(d), Fr(2))
    if x == -d:
        return (Fr(-d), Fr(-2 * d))
    return (x, x - d)


class F2Span:
    """Row-reduced span of bit vectors."""

    def __init__(self):
        self.rows = {}  # pivot bit -> row

    def reduce(self, v):
        """Canonical representative of v modulo the span (no pivot bit set); linear in v."""
        for h in sorted(self.rows, reverse=True):
            if v >> h & 1:
                v ^= self.rows[h]
        return v

    def add(self, v):
        v = self.reduce(v)
        if v:
            self.rows[v.bit_length() - 1] = v
            return True
        return False

    def dim(self):
        return len(self.rows)


@lru_cache(maxsize=None)
def image_Q2(d0):
    """Local image at 2 for C_{d0}, as a frozenset of 6-bit vectors (cls2(first) | cls2(second)<<3)."""
    rng = random.Random(12345 + d0)
    sp = F2Span()
    pts = [Fr(0), Fr(d0), Fr(-d0)]
    tries = 0
    while sp.dim() < 3:
        tries += 1
        assert tries < 200000, ("2-adic sampling failed", d0)
        if pts:
            x = pts.pop()
        else:
            k = rng.randint(-6, 6)
            u = rng.randrange(1, 2 ** 10, 2) * rng.choice([1, -1])
            base = rng.choice([0, d0, -d0])
            x = Fr(base) + Fr(u) * Fr(2) ** k
            if x == 0:
                continue
        f = x * (x - d0) * (x + d0)
        if f != 0 and not is_sq_Q2(f):
            continue
        a, b = kummer(x, d0)
        sp.add(cls2(a) | (cls2(b) << 3))
    # enumerate the span
    rows = list(sp.rows.values())
    span = set()
    for mask in range(1 << len(rows)):
        v = 0
        for i, r in enumerate(rows):
            if mask >> i & 1:
                v ^= r
        span.add(v)
    return frozenset(span)


def rep2(d):
    """Representative of the class of d in Q_2*/Q_2*^2 among 1,3,5,7,2,6,10,14."""
    v = vp(d, 2)
    u = (d // 2 ** v) % 8
    return u * (2 if v % 2 else 1)


def primes_of(n, factor):
    return sorted(factor(abs(n)))


def selmer(d, dprimes):
    """2-Selmer group of C_d (d squarefree nonzero integer, dprimes = its odd primes).

    Returns (basis_list, gens) where gens = [-1, 2] + odd primes, and each Selmer element is a
    pair (a, b) of bitmasks over gens (first and second Kummer coordinate)."""
    gens = [-1, 2] + list(dprimes)
    k = len(gens)
    # local maps: list of (function g->local vector, local image as set or span)
    # Encode candidate g = a | (b << k).
    N = 2 * k
    constraints = []  # list of (list of local vectors of basis elements, image span F2Span)

    # place 2
    img2 = image_Q2(rep2(d))
    loc2 = []
    for i in range(N):
        g = gens[i % k]
        c = cls2(g)
        loc2.append(c if i < k else c << 3)
    constraints.append((loc2, img2))
    # real place
    locR = []
    for i in range(N):
        g = gens[i % k]
        s = 1 if g < 0 else 0
        locR.append(s if i < k else s << 1)
    imgR = {0, 0b11} if d > 0 else {0, 0b01}
    constraints.append((locR, frozenset(imgR)))
    # odd primes of d
    for p in dprimes:
        locp = []
        for i in range(N):
            g = gens[i % k]
            if g == p:
                c = 1
            else:
                c = leg(g, p) << 1
            locp.append(c if i < k else c << 2)

        def clsp(r, p=p):
            r = Fr(r)
            num, den = r.numerator, r.denominator
            v = vp(num, p) - vp(den, p)
            u = (num // p ** vp(num, p)) * (den // p ** vp(den, p))
            return (v % 2) | (leg(u, p) << 1)

        tors = [(d, 2), (-d, -2 * d), (-1, -d)]
        imgp = set()
        for mask in range(4):
            v = 0
            for j in range(2):
                if mask >> j & 1:
                    a, b = tors[j]
                    v ^= clsp(a) | (clsp(b) << 2)
            imgp.add(v)
        imgsp = F2Span()
        for t in tors:
            imgsp.add(clsp(t[0]) | (clsp(t[1]) << 2))
        assert imgsp.dim() == 2, ("torsion image not injective", d, p)
        constraints.append((locp, frozenset(imgp)))

    # Selmer = kernel of g -> (L_v(g) mod W_v)_v.  Quotient by W_v: choose complement coordinates.
    # Build big linear map: for each place, reduce local vector modulo span of W_v, using a fixed
    # reduction; the reduced vector is linear in g.
    cols = [0] * N
    shift = 0
    for loc, img in constraints:
        sp = F2Span()
        for w in img:
            sp.add(w)
        width = max(1, max(x.bit_length() for x in list(img) + loc))
        for i in range(N):
            cols[i] |= sp.reduce(loc[i]) << shift
        shift += width + 1
    # kernel of the map F2^N -> F2^shift, columns cols[i]
    # Gaussian elimination tracking combinations
    piv = {}  # pivot bit -> (vector, combination)
    kernel = []
    for i in range(N):
        v, comb = cols[i], 1 << i
        while v:
            h = v.bit_length() - 1
            if h in piv:
                pv, pc = piv[h]
                v ^= pv
                comb ^= pc
            else:
                piv[h] = (v, comb)
                break
        if v == 0:
            kernel.append(comb)
    basis = [(c & ((1 << k) - 1), c >> k) for c in kernel]
    return basis, gens


def vec_of(r, gens):
    """Bitmask over gens of the squareclass of the nonzero integer r (must be supported on gens)."""
    m = 0
    if r < 0:
        m |= 1
    r = abs(r)
    for i, g in enumerate(gens):
        if i == 0:
            continue
        e = vp(r, g)
        if e % 2:
            m |= 1 << i
        r //= g ** e
    assert r == 1, "not supported on gens"
    return m


def first_coord_contains(basis, target):
    sp = F2Span()
    for a, b in basis:
        sp.add(a)
    return sp.reduce(target) == 0
